Algorithm SumaFilas
  Dimension m[3, 3] As Integer;
  For f <- 0 To 2 Do
    For c <- 0 To 2 Do
      Read m[f, c];
    EndFor
  EndFor
  For f <- 0 To 2 Do
    Define suma As Integer <- 0;
    For c <- 0 To 2 Do
      suma <- suma + m[f, c];
    EndFor
    Write suma;
  EndFor
EndAlgorithm
